include "globals.mzn";

% Input data
int: num_children = 5;
array[1..num_children] of string: children = ["Bernice", "Carl", "Debby", "Sammy", "Ted"];
array[1..num_children] of string: countries = ["Ethiopia", "Kazakhstan", "Lithuania", "Morocco", "Yemen"];
array[1..num_children] of string: stories = ["burning bush", "captivity", "Moses's youth", "Passover", "the Ten Commandments"];
array[1..num_children] of int: ages = [3, 5, 7, 8, 10];

% Decision Variables
array[1..num_children] of var 1..num_children: child_order;
array[1..num_children] of var 1..num_children: country_order;
array[1..num_children] of var 1..num_children: story_order;
array[1..num_children] of var 1..num_children: age_order;

% Constraints
% All children, countries, stories, and ages are different
constraint all_different([child_order[i] | i in 1..num_children]);
constraint all_different([country_order[i] | i in 1..num_children]);
constraint all_different([story_order[i] | i in 1..num_children]);
constraint all_different([age_order[i] | i in 1..num_children]);

% 1. Debby’s family is from Lithuania.
constraint child_order[3] = country_order[3];

% 2. The child who told the story of the Passover is two years older than Bernice.
constraint exists(i in 1..num_children) (
    child_order[i] = 1 /\ story_order[i] = 4 /\ age_order[i] = age_order[exists(j in 1..num_children)(child_order[j] = 2)] + 2
);

% 3. The child whose family is from Yemen is younger than the child from the Ethiopian family.
constraint exists(i in 1..num_children) (
    exists(j in 1..num_children) (
        country_order[i] = 5 /\ country_order[j] = 1 /\ age_order[i] < age_order[j]
    )
);

% 4. The child from the Moroccan family is three years older than Ted.
constraint exists(i in 1..num_children) (
    child_order[i] = 5 /\ country_order[i] = 4 /\ age_order[i] = age_order[exists(j in 1..num_children)(child_order[j] = 5)] + 3
);

% 5. Sammy is three years older than the child who told the story of Moses’s youth in the house of the Pharaoh.
constraint exists(i in 1..num_children) (
    child_order[i] = 4 /\ story_order[i] = 3 /\ age_order[i] = age_order[exists(j in 1..num_children)(story_order[j] = 3)] + 3
);

% Associations between the lists
constraint forall(i in 1..num_children) (
    child_order[i] = country_order[i] /\ 
    child_order[i] = story_order[i] /\ 
    child_order[i] = age_order[i]
);

solve satisfy;

output [
    "{",
    join(",", [
        "\"ages\": " ++ show([index(ages, age_order[i]) | i in 1..num_children]),
        "\"children\": " ++ show([child_order[i] | i in 1..num_children]),
        "\"countries\": " ++ show([country_order[i] | i in 1..num_children]),
        "\"stories\": " ++ show([story_order[i] | i in 1..num_children])
    ]),
    "}"
];
```

