% Define the number of cows and sons
int: num_cows = 25;
int: num_sons = 5;

% Define the number of cows to be assigned to each son
array[1..num_sons] of int: num_cows_per_son = [7, 6, 5, 4, 3];

% Define the milk production of each cow
array[1..num_cows] of int: milk_production = [i | i in 1..num_cows];

% Decision variable: assignment of cows to sons
array[1..num_cows] of var 0..num_sons-1: cow_assignments;

% Constraints: each cow is assigned to exactly one son
constraint forall (c in 1..num_cows) (
    cow_assignments[c] != 0 <-> exists (s in 1..num_sons) (c in index_set(milk_production_cows[s]))
);

% Constraints: number of cows per son
array[1..num_sons] of var set of 1..num_cows: milk_production_cows;
constraint forall (s in 1..num_sons) (
    card(milk_production_cows[s]) = num_cows_per_son[s] /\
    forall (c in milk_production_cows[s]) (cow_assignments[c] = s-1)
);
constraint partition_set(milk_production_cows, 1..num_cows);

% Constraints: total milk production per son is equal
array[1..num_sons] of var int: total_milk_per_son;
constraint forall (s in 1..num_sons) (
    total_milk_per_son[s] = sum(c in milk_production_cows[s]) (milk_production[c])
);
constraint all_equal(total_milk_per_son);

% Solve the problem
solve satisfy;

% Output the solution
output ["{\"cow_assignments\": [" ++ join(", ", [show(cow_assignments[c]) | c in 1..num_cows]) ++ "]}"];
```

