% Define the number of people and floors
int: num_people = 5;
set of int: People = 1..num_people;
set of int: Floors = 1..num_people;

% Input data: Names of the people
array[People] of string: names = ["B", "C", "F", "M", "S"];

% Decision Variables: Floor assignment for each person
array[People] of var Floors: floor;

% Constraints: Each person lives on a different floor
constraint all_different([floor[p] | p in People]);

% Baker does not live on the fifth floor
constraint floor[1] != 5;

% Cooper does not live on the first floor
constraint floor[2] != 1;

% Fletcher does not live on the first or fifth floor
constraint floor[3] != 1;
constraint floor[3] != 5;

% Miller lives on a higher floor than Cooper
constraint floor[4] > floor[2];

% Smith does not live on a floor adjacent to Fletcher's
constraint abs(floor[5] - floor[3]) > 1;

% Fletcher does not live on a floor adjacent to Cooper's
constraint abs(floor[3] - floor[2]) > 1;

% Solve the problem
solve satisfy;

% Output the solution in JSON format
output ["{", 
        join(",", [
            "\"B\": " ++ show(floor[1]),
            "\"C\": " ++ show(floor[2]),
            "\"F\": " ++ show(floor[3]),
            "\"M\": " ++ show(floor[4]),
            "\"S\": " ++ show(floor[5])
        ]),
        "}"
];
