set of int: COLS = 1..n;

% Define the decision variables: the value in each cell of the grid
array[ROWS, COLS] of var 1..n*n: square;

% Each cell contains a different integer from 1 to n^2
constraint all_different(array1d(square));

% The sum of integers in each row is equal to n(n^2+1)/2
constraint forall(r in ROWS) (
    sum([square[r, c] | c in COLS]) = n*(n*n + 1) div 2
);

% The sum of integers in each column is equal to n(n^2+1)/2
constraint forall(c in COLS) (
    sum([square[r, c] | r in ROWS]) = n*(n*n + 1) div 2
);

% The sum of integers in the main diagonal is equal to n(n^2+1)/2
constraint sum([square[i, i] | i in ROWS]) = n*(n*n + 1) div 2;

% The sum of integers in the anti-diagonal is equal to n(n^2+1)/2
constraint sum([square[i, n-i+1] | i in ROWS]) = n*(n*n + 1) div 2;

% Solve the model
solve satisfy;

% Print the magic square as a list of lists
output [
    "{",
    "\"square\": [",
    join(",\n", [ "[" ++ join(",", [show(square[r, c]) | c in COLS]) ++ "]" | r in ROWS]),
    "]",
    "}"
];
```

