array[1..num_jobs] of int: num_tasks = [length(jobs_data[j]) | j in 1..num_jobs];
array[1..num_jobs, 1..max(num_tasks)] of int: machine;
array[1..num_jobs, 1..max(num_tasks)] of int: duration;

% Extract and process the provided data
constraint forall(j in 1..num_jobs, t in 1..num_tasks[j]) (
    machine[j, t] = jobs_data[j, t, 1] + 1 /\
    duration[j, t] = jobs_data[j, t, 2]
);

% Decision Variables
array[1..num_jobs, 1..max(num_tasks)] of var 0..sum(j in 1..num_jobs, t in 1..num_tasks[j]) (duration[j, t]): start;
array[1..num_jobs] of var 0..sum(j in 1..num_jobs, t in 1..num_tasks[j]) (duration[j, t]): end_time;
var 0..sum(j in 1..num_jobs, t in 1..num_tasks[j]) (duration[j, t]): makespan;

% Constraints
constraint forall(j in 1..num_jobs) (
    end_time[j] = start[j, num_tasks[j]] + duration[j, num_tasks[j]]
);

constraint forall(j in 1..num_jobs, t in 1..num_tasks[j]-1) (
    start[j, t+1] >= start[j, t] + duration[j, t]
);

constraint forall(m in 1..max(machine)) (
    cumulative([start[j, t] | j in 1..num_jobs, t in 1..num_tasks[j] where machine[j, t] == m],
                [duration[j, t] | j in 1..num_jobs, t in 1..num_tasks[j] where machine[j, t] == m],
                [1 | j in 1..num_jobs, t in 1..num_tasks[j] where machine[j, t] == m])
);

constraint makespan >= max(end_time);

% Solve the model
solve minimize makespan;

% Print the solution in JSON format
output [
    "{",
    "\"makespan\": " ++ show(makespan),
    "}"
];

