% Constraint to ensure valid movements between steps
constraint forall (s in 0..N-1) (
    let {
        var 1..num_rows: empty_row;
        var 1..num_cols: empty_col;
        var 1..num_rows: new_empty_row;
        var 1..num_cols: new_empty_col;
    } in (
        % Find the position of the empty tile at step s
        exists (i in 1..num_rows, j in 1..num_cols) (
            steps[s, i, j] = 0 /\ empty_row = i /\ empty_col = j
        ) /\
        % Choose a valid movement
        (
            (new_empty_row = empty_row + 1 /\ new_empty_col = empty_col /\ new_empty_row <= num_rows /\ empty_row > 1) \/
            (new_empty_row = empty_row - 1 /\ new_empty_col = empty_col /\ new_empty_row >= 1 /\ empty_row < num_rows) \/
            (new_empty_row = empty_row /\ new_empty_col = empty_col + 1 /\ new_empty_col <= num_cols /\ empty_col > 1) \/
            (new_empty_row = empty_row /\ new_empty_col = empty_col - 1 /\ new_empty_col >= 1 /\ empty_col < num_cols)
        ) /\
        % Update the state at step s+1
        forall (i in 1..num_rows, j in 1..num_cols) (
            if (i = new_empty_row /\ j = new_empty_col) then
