                steps[s+1, i, j] = steps[s, new_empty_row, new_empty_col]
            else
                steps[s+1, i, j] = steps[s, i, j]
            endif
        )
    )
);

% Define the constraint to ensure all tiles are used exactly once in each step
constraint forall (s in 0..N) (
    alldifferent([steps[s, i, j] | i in 1..num_rows, j in 1..num_cols])
);

