% Include the global constraints library for cumulative constraint
include "globals.mzn";

% Input data processing
int: num_jobs = length(durations_data);
int: num_resources = length(resource_capacities_data);
array[1..num_jobs] of int: durations = array1d(1..num_jobs, durations_data);
array[1..num_jobs, 1..num_resources] of int: resource_needs = array2d(1..num_jobs, 1..num_resources, resource_needs_data);
array[1..num_resources] of int: resource_capacities = array1d(1..num_resources, resource_capacities_data);

% Extracting precedence constraints from successors_link_data
set of int: successors_link_set = {i | i in 1..length(successors_link_data)};
array[successors_link_set] of 1..num_jobs: predecessors = array1d(successors_link_set, [successors_link_data[i,1] + 1 | i in successors_link_set]);
array[successors_link_set] of 1..num_jobs: successors = array1d(successors_link_set, [successors_link_data[i,2] + 1 | i in successors_link_set]);

% Decision Variables
array[1..num_jobs] of var int: start_time;
var int: makespan;

% Constraints
% Precedence constraints
constraint forall(i in successors_link_set) (
    start_time[predecessors[i]] + durations[predecessors[i]] <= start_time[successors[i]]
);

% Resource constraints using cumulative
constraint forall(r in 1..num_resources) (
    cumulative(start_time, durations, [resource_needs[j, r] | j in 1..num_jobs], resource_capacities[r])
);

% Makespan is the maximum end time of all jobs
constraint forall(j in 1..num_jobs) (
    start_time[j] + durations[j] <= makespan
);

% Objective: Minimize makespan
solve minimize makespan;

% Output the start times of the jobs in JSON format
output [
    "{",
    "\"start_time\": [" ++ join(", ", [show(start_time[j]) | j in 1..num_jobs]) ++ "]",
    "}"
];
