% Template Design Problem

% Include necessary libraries
include "globals.mzn";

% Input data
int: n_slots = 9;  % The amount of slots on a template
int: n_templates = 2;  % The amount of templates
int: n_var = 7;  % The amount of different variations
array[1..n_var] of int: demand;  % The demand per variation

% Decision Variables
array[1..n_templates, 1..n_slots] of var 0..n_var: layout;  % The layout of the templates
array[1..n_templates] of var int: production;  % The number of printed sheets per template
var int: total_production;  % The total number of printed sheets

% Constraints
constraint forall(t in 1..n_templates) (
  forall(s in 1..n_slots) (
    layout[t, s] != 0 -> sum(v in 1..n_var where v == layout[t, s])(demand[v]) >= production[t]
  )
);

constraint forall(v in 1..n_var) (
  sum(t in 1..n_templates, s in 1..n_slots where layout[t, s] == v)(production[t]) >= demand[v]
);

constraint total_production = sum(t in 1..n_templates)(production[t]);

% Redundant constraint to help the solver
constraint forall(t in 1..n_templates) (
  production[t] >= min([demand[v] | v in 1..n_var where exists(s in 1..n_slots)(layout[t, s] == v)])
);

% Solve to minimize the total production
solve minimize total_production;

% Output the solution in JSON format
output [
  "{",
  join(",", [
    "\"production\": " ++ show(total_production),
    "\"layout\": [" ++ join(",", [show([layout[t, s] | s in 1..n_slots]) | t in 1..n_templates]) ++ "]"
  ]),
  "}"
];
```

