% Low Autocorrelation Binary Sequences Problem

% Include necessary libraries
include "globals.mzn";

% Input data
int: n = 10;  % Length of the binary sequence

% Decision Variables
array[1..n] of var -1..1: sequence;  % Binary sequence where each element is either -1 or 1

% Constraints: Ensure that the sequence elements are either -1 or 1
constraint forall(i in 1..n) (
    sequence[i] in {-1, 1}
);

% Function to calculate the k-th autocorrelation with non-periodic boundary conditions
function var int: autocorrelation_non_periodic(int: k) =
    sum(i in 1..n-k) (sequence[i] * sequence[i+k]);

% Function to calculate the k-th autocorrelation with periodic boundary conditions
function var int: autocorrelation_periodic(int: k) =
    sum(i in 1..n) (sequence[i] * sequence[(i+k-1) mod n + 1]);

% Calculate the sum of the squares of the autocorrelations (Energy)
var int: E_non_periodic = sum(k in 1..n-1) (autocorrelation_non_periodic(k)^2);
var int: E_periodic = sum(k in 1..n-1) (autocorrelation_periodic(k)^2);

% Solve to minimize the energy (sum of squares of autocorrelations) with periodic boundary conditions
solve minimize E_periodic;

% Output the binary sequence and the energy value in JSON format
output [
    "{",
    join(",", [
        "\"sequence\": " ++ show([sequence[i] | i in 1..n]),
        "\"E\": " ++ show(E_periodic)
    ]),
    "}"
];
```

