    [bottom[c] | c in 1..n_containers],
    [if rotated[c] then width[c] else length[c] endif | c in 1..n_containers],
    [if rotated[c] then length[c] else width[c] endif | c in 1..n_containers],
    deck_width
);

constraint forall (c1 in 1..n_containers, c2 in c1+1..n_containers) (
    let {
        int: w1 = width[c1];
        int: l1 = length[c1];
        int: w2 = width[c2];
        int: l2 = length[c2];
