% Input data
int: base = 6;  % Side length of the large square
array[int] of int: sides = [3, 3, 3, 2, 1, 1, 1, 1, 1];  % Side lengths of the smaller squares
int: num_squares = length(sides);

% Decision Variables
array[1..num_squares] of var 0..base: x_coords;  % X-coordinates of the bottom-left corner of the squares
array[1..num_squares] of var 0..base: y_coords;  % Y-coordinates of the bottom-left corner of the squares

% Constraints
constraint forall (i in 1..num_squares) (
    x_coords[i] + sides[i] <= base  % Ensure the square is within the large square horizontally
    /\ y_coords[i] + sides[i] <= base  % Ensure the square is within the large square vertically
);

constraint forall (i, j in 1..num_squares where i < j) (
    not (x_coords[i] <= x_coords[j] + sides[j] - 1  % Check if square i is to the right of square j
         /\ x_coords[j] <= x_coords[i] + sides[i] - 1  % Check if square j is to the right of square i
         /\ y_coords[i] <= y_coords[j] + sides[j] - 1  % Check if square i is below square j
         /\ y_coords[j] <= y_coords[i] + sides[i] - 1)  % Check if square j is below square i
);

constraint sum(i in 1..num_squares) (sides[i] * sides[i]) = base * base;  % Ensure the sum of the squares' areas equals the large square's area

% Redundant constraint to improve performance by ensuring non-overlapping
constraint disjoint2d([x_coords[i] | i in 1..num_squares], [y_coords[i] | i in 1..num_squares], [sides[i] | i in 1..num_squares], [sides[i] | i in 1..num_squares]);

solve satisfy;

output [
    "{",
    join(",", [
        "\"x_coords\": [" ++ join(",", [show(x_coords[i]) | i in 1..num_squares]) ++ "]",
        "\"y_coords\": [" ++ join(",", [show(y_coords[i]) | i in 1..num_squares]) ++ "]"
    ]),
    "}"
];
