% Social Golfers Problem

% Include necessary library for global constraints
include "globals.mzn";

% Input data
int: n_weeks = 4;  % Number of weeks
int: n_groups = 3;  % Number of groups
int: group_size = 3;  % Size of each group
int: n_golfers = n_groups * group_size;  % Total number of golfers

% Decision Variables
array[1..n_golfers, 1..n_weeks] of var 1..n_groups: assign;

% Constraints
constraint forall (w in 1..n_weeks) (
    forall (g in 1..n_groups) (
        count([assign[i, w] | i in 1..n_golfers], g) == group_size
    )
);

constraint forall (i in 1..n_golfers, j in i+1..n_golfers, w1 in 1..n_weeks, w2 in w1+1..n_weeks) (
    (assign[i, w1] == assign[j, w1] /\ assign[i, w2] == assign[j, w2]) -> false
);

% Redundant constraint to improve performance
constraint forall (w in 1..n_weeks) (
    all_different([i * n_groups + assign[i, w] | i in 1..n_golfers])
);

solve satisfy;

% Output the assignments of golfers to groups for each week
output [
    "{",
    "\"assign\": [",
    join(",\n", [
        "[" ++ join(",", [show(assign[i, w]) | i in 1..n_golfers]) ++ "]"
        | w in 1..n_weeks
    ]),
    "]",
    "}"
];
```

