```minizinc
% Include necessary libraries
include "globals.mzn";

% Input data
int: n_teams = 9;
int: n_days = 18;

% Sets
set of int: TEAMS = 1..n_teams;
set of int: DAYS = 1..n_days;

% Constants for teams
int: Clem = 1;
int: Duke = 2;
int: FSU = 3;
int: GT = 4;
int: UMD = 5;
int: UNC = 6;
int: NCSt = 7;
int: UVA = 8;
int: Wake = 9;

% Constants for match configuration
enum MatchConfig = {Home, Away, Bye};

% Mirroring scheme
array[DAYS] of int: mirror = [8, 9, 12, 13, 14, 15, 16, 1, 2, 17, 18, 3, 4, 5, 6, 7, 10, 11];

% Decision Variables
array[TEAMS, DAYS] of var MatchConfig: where;
array[TEAMS, TEAMS, DAYS] of var bool: config;

% Constraints
constraint forall(t in TEAMS, d in DAYS) (
    where[t, d] = Home <-> exists(o in TEAMS where o != t) (config[t, o, d] /\ where[o, d] = Away)
);

constraint forall(t1 in TEAMS, t2 in TEAMS, d in DAYS where t1 != t2) (
    config[t1, t2, d] <-> config[t2, t1, mirror[d]]
);

constraint forall(t in TEAMS, d in DAYS) (
    sum([config[t, o, d] | o in TEAMS where o != t]) + (where[t, d] = Bye) = 1
);

constraint forall(t in TEAMS) (
    let { array[1..2] of var int: last_two = [where[t, n_days-1], where[t, n_days]]; } in
    count(last_two, Away) != 2
);

constraint forall(t in TEAMS, d in 3..n_days) (
    (where[t, d-2] = Away /\ where[t, d-1] = Away) -> where[t, d] != Away
);

constraint forall(t in TEAMS, d in 3..n_days) (
    (where[t, d-2] = Home /\ where[t, d-1] = Home) -> where[t, d] != Home
);

constraint forall(t in TEAMS, d in 4..n_days) (
    count([where[t, d-3], where[t, d-2], where[t, d-1]], Away) <= 2
);

constraint forall(t in TEAMS, d in 5..n_days) (
    count([where[t, d-4], where[t, d-3], where[t, d-2], where[t, d-1]], Home) <= 3
);

constraint forall(t in TEAMS) (
    let { array[2, 4, 6, 8, 10] of var MatchConfig: weekends = [where[t, w] | w in 2, 4, 6, 8, 10, 12, 14, 16, 18]] in 
         count(weekends, Home) = 4 /\ count(weekends, Away) = 4 /\ count(weekends, Bye) = 1
);

constraint forall(t in TEAMS) (
    count([where[t, w] | w in [2, 4, 6, 8, 10]], {Home, Bye}) >= 2
);

constraint forall(d in {Duke, Clem, UMD, NCSt}) (
    let { int: r = case d in {Duke: UNC, Clem: GT, UMD: UVA, NCSt: Wake} } in
    (config[d, r, n_days] \/ config[d, FSU, n_days] \/ (where[d, n_days] = Bye))
);

constraint forall(t in {Wake, GT}) (
    exists(d in 11..18) (config[t, UNC, d]) /\ exists(d in 11..18) (config[t, Duke, d])
);

constraint forall(t in TEAMS, d in 2..n_days) (
    (config[t, UNC, d-1] /\ where[t, d-1] = Away /\ config[t, Duke, d] /\ where[t, d] = Away) -> 
    (not config[t, _, d+1] /\ where[t, d+1] = Away)
);

constraint forall(t in TEAMS, d in 3..n_days) (
    (config[t, UNC, d-2] /\ config[t, Duke, d-1] /\ config[t, Wake, d]) -> false
);

constraint config[UNC, Duke, n_days];
constraint config[UNC, Duke, 11];
constraint config[UNC, Clem, 2];
constraint where[Duke, 16] = Bye;
constraint where[Wake, 17] != Home;
constraint where[Wake, 1] = Bye;
constraint where[Clem, 1] != Away;
constraint where[Duke, 1] != Away;
constraint where[UMD, 1] != Away;
constraint where[Wake, 1] != Away;
constraint where[Clem, n_days] != Away;
constraint where[Duke, n_days] != Away;
constraint where[UMD, n_days] != Away;
constraint where[Wake, n_days] != Away;
constraint where[FSU, n_days] != Bye;
constraint where[NCSt, n_days] != Bye;
constraint where[UNC, 1] != Bye;

% Solve
solve satisfy;

% Output
output [
    "{",
    "\"config\": [", join(",\n", [ "[ " ++ join(",", [if config[t1, t2, d] then "1" else "0" endif | t2 in TEAMS]) ++ " ]" | t1 in TEAMS, d in DAYS]), "],",
    "\"where\": [", join(",\n", [ "[ " ++ join(",", [show(where[t, d]) | d in DAYS]) ++ " ]" | t in TEAMS]), "]",
    "}"
];
