% Include necessary libraries
include "globals.mzn";

% Input data
int: n_boats;  % Number of boats
int: n_periods;  % Number of periods
array[1..n_boats] of int: capacity;  % Capacities of the boats
array[1..n_boats] of int: crew_size;  % Crew sizes of the boats

% Decision Variables
array[1..n_boats] of var bool: is_host;  % Whether a boat is a host
array[1..n_periods, 1..n_boats, 1..n_boats] of var bool: visits;  % Visit schedule

% Constraints
% A boat cannot be both a host and a guest at the same time
constraint forall(p in 1..n_periods, b in 1..n_boats) (
    is_host[b] \/ not exists(h in 1..n_boats) (visits[p, b, h])
);

% A guest boat cannot revisit a host
constraint forall(p1 in 1..n_periods, p2 in 1..n_periods where p1 < p2, b in 1..n_boats, h in 1..n_boats) (
    (visits[p1, b, h] /\ is_host[h]) -> not visits[p2, b, h]
);

% Guest crews cannot meet more than once
constraint forall(p1 in 1..n_periods, p2 in 1..n_periods where p1 < p2, b1 in 1..n_boats, b2 in 1..n_boats where b1 < b2) (
    not (exists(h in 1..n_boats) (visits[p1, b1, h] /\ visits[p2, b2, h] /\ is_host[h]) /\ exists(h in 1..n_boats) (visits[p2, b1, h] /\ visits[p1, b2, h] /\ is_host[h]))
);

% The total number of people aboard a host boat must not exceed its capacity
constraint forall(p in 1..n_periods, h in 1..n_boats where is_host[h]) (
    crew_size[h] + sum(b in 1..n_boats where visits[p, b, h]) * crew_size[b] <= capacity[h]
);

% Solve to minimize the number of host boats
solve minimize sum(b in 1..n_boats) (bool2int(is_host[b]));

% Output the solution in JSON format
output [
    "{",
    "\"visits\": [" ++ join(",", [
        "[" ++ join(",", [
            "[" ++ join(",", [show(bool2int(visits[p, b, h])) | h in 1..n_boats]) ++ "]" | b in 1..n_boats
        ]) ++ "]" | p in 1..n_periods
    ]) ++ "],",
    "\"is_host\": [" ++ join(",", [show(bool2int(is_host[b])) | b in 1..n_boats]) ++ "]",
    "}"
];
```

