array[1..n, 1..c] of var bool: M;  % M[i, j] is true if ball i is in box j

% Constraints
constraint forall(i in 1..n) (
    sum(j in 1..c)(bool2int(M[i, j])) == 1  % Each ball is in exactly one box
);

constraint forall(x in 1..n, y in x..n, z in 1..n where x + y == z, j in 1..c) (
    M[x, j] + M[y, j] + M[z, j] <= 2  % For any triple (x, y, z) with x + y = z, not all are in the same box
);

% Solve the model
solve satisfy;

% Output the solution
output ["{\"balls\": [" ++ join(", ", [sum(j in 1..c)(j * bool2int(M[i, j])) | i in 1..n]) ++ "]}"];
