    position[i] + i + 1 <= total_numbers /\
    solution[position[i]] = i /\
    solution[position[i] + i + 1] = i
);

constraint forall(j in 1..total_numbers) (
    exists(i in 1..n) (j = position[i] \/ j = position[i] + i + 1) <-> solution[j] != 0
);

constraint forall(j in 1..total_numbers) (
    if solution[j] = 0 then 
        forall(i in 1..n) (j != position[i] /\ j != position[i] + i + 1)
