    endif
);

% Redundant constraint to improve performance
constraint forall(i in 1..n) (
    position[i] <= total_numbers - i - 1
);

solve satisfy;

output [
    "{",
    join(",", [
        "\"position\": [" ++ join(",", [show(position[i]) | i in 1..n]) ++ "]",
        "\"solution\": [" ++ join(",", [show(solution[j]) | j in 1..total_numbers]) ++ "]"
    ]),
    "}"
];
