% Sports Tournament Scheduling

% Include necessary libraries
include "globals.mzn";

% Input data
int: n_teams = 8;  % Number of teams
int: n_weeks = n_teams - 1;  % Number of weeks
int: n_periods = n_teams div 2;  % Number of periods per week

% Decision Variables
array[1..n_weeks, 1..n_periods, 1..2] of var 1..n_teams: schedule;

% Constraints
constraint forall (w in 1..n_weeks) (
    % Every team plays once a week
    forall (t in 1..n_teams) (
        exactly1([schedule[w, p, i] | p in 1..n_periods, i in 1..2] , t)
    )
);

constraint forall (t in 1..n_teams) (
    % Every team plays at most twice in the same period over the tournament
    forall (p in 1..n_periods) (
        sum([schedule[w, p, i] == t | w in 1..n_weeks, i in 1..2]) <= 2
    )
);

constraint forall (t1 in 1..n_teams, t2 in t1+1..n_teams) (
    % Every team plays every other team
    exists(w in 1..n_weeks, p in 1..n_periods, i1 in 1..2, i2 in 1..2 where i1 != i2) (
        (schedule[w, p, i1] == t1 /\ schedule[w, p, i2] == t2) \/ (schedule[w, p, i1] == t2 /\ schedule[w, p, i2] == t1)
    )
);

% Symmetry breaking: the first week is fixed to reduce search space
constraint forall (p in 1..n_periods) (
    (schedule[1, p, 1] = 2*p-1) /\ (schedule[1, p, 2] = 2*p)
);

% Solve the model
solve satisfy;

% Output the solution
array[1..n_weeks, 1..n_periods] of var 1..n_teams: home = [schedule[w, p, 1] | w in 1..n_weeks, p in 1..n_periods];
array[1..n_weeks, 1..n_periods] of var 1..n_teams: away = [schedule[w, p, 2] | w in 1..n_weeks, p in 1..n_periods];

output [
    "{",
    "\"home\": " ++ show([home[w, p] | w in 1..n_weeks, p in 1..n_periods]) ++ ", ",
    "\"away\": " ++ show([away[w, p] | w in 1..n_weeks, p in 1..n_periods]) ++ "}",
];
