% BIBD Model in Minizinc

% Include the globals library for the 'sum' constraint
include "globals.mzn";

% Input data
int: v = 9;  % Number of distinct objects
int: b = 12;  % Number of blocks
int: r = 4;   % Number of blocks each object occurs in
int: k = 3;   % Number of objects each block contains
int: l = 1;   % Number of blocks in which each pair of distinct objects occurs together

% Decision Variables: Incidence Matrix
array[1..v, 1..b] of var 0..1: matrix;

% Constraints
% Each object occurs in exactly r blocks
constraint forall (i in 1..v) (
    sum([matrix[i, j] | j in 1..b]) = r
);

% Each block contains exactly k objects
constraint forall (j in 1..b) (
    sum([matrix[i, j] | i in 1..v]) = k
);

% Every two distinct objects occur together in exactly λ blocks
constraint forall (i1 in 1..v, i2 in i1+1..v) (
    sum([matrix[i1, j] * matrix[i2, j] | j in 1..b]) = l
);

% Solve the model
solve satisfy;

% Output the incidence matrix in JSON format
output [
    "{",
    "\"matrix\": [",
    join(",\n", [ "[" ++ join(",", [show(matrix[i, j]) | j in 1..b]) ++ "]" | i in 1..v]),
    "]",
    "}"
];
