% DNA Word Design Problem

% Include the globals library for global constraints
include "globals.mzn";

% Input data
int: n = 8;  % Number of words to find
int: word_length = 8;  % Length of each word
int: num_symbols = 4;  % Size of the alphabet {A, C, G, T}
int: min_diff = 4;  % Minimum difference between words and their complements/reverses

% Define the alphabet and mapping for Watson-Crick complement
array[1..num_symbols] of string: alphabet = ["A", "C", "G", "T"];
array[1..num_symbols] of int: complement_map = [4, 3, 2, 1];  % A <-> T, C <-> G

% Decision Variables
array[1..n, 1..word_length] of var 1..num_symbols: words;  % The set S of words

% Constraints
constraint
    forall(i in 1..n) (
        % Each word has exactly 4 symbols from {C, G}
        sum(j in 1..word_length) (words[i, j] = 2 \/ words[i, j] = 3) = 4
    );

constraint
    forall(i1, i2 in 1..n where i1 < i2) (
        % Each pair of distinct words differ in at least min_diff positions
        sum(j in 1..word_length) (words[i1, j] != words[i2, j]) >= min_diff
    );

constraint
    forall(i1, i2 in 1..n) (
        % x^R and y^C differ in at least min_diff positions for all x, y in S
        let {
            array[1..word_length] of var int: reverse_i1 = [words[i1, word_length - j + 1] | j in 1..word_length];
            array[1..word_length] of var int: complement_i2 = [complement_map[words[i2, j]] | j in 1..word_length]
        } in
        sum(j in 1..word_length) (reverse_i1[j] != complement_i2[j]) >= min_diff
    );

% Solve to satisfy the constraints
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    "\"words\": [",
    join(",\n", [ "[" ++ join(",", [ "\"" ++ alphabet[words[i, j]] ++ "\"" | j in 1..word_length]) ++ "]" | i in 1..n]),
    "]",
    "}"
];
