% Steiner Triple Systems
int: n = 9;  % Order of the Steiner Triple System

% Calculate the number of triples
int: num_triples = n * (n-1) div 6;

% Decision Variables: 
% A matrix where each row represents a triple
array[1..num_triples, 1..3] of var 1..n: triples;

% Constraints:
% Each triple contains distinct elements
constraint forall(t in 1..num_triples) (
    all_different([triples[t, i] | i in 1..3])
);

% Any two triples have at most one common element
constraint forall(t1 in 1..num_triples, t2 in t1+1..num_triples) (
    count([triples[t1, i] | i in 1..3], [triples[t2, j] | j in 1..3]) <= 1
);

% Symmetry breaking: Order the triples lexicographically
constraint forall(t1 in 1..num_triples-1, t2 in t1+1..num_triples) (
    triples[t1, 1] <= triples[t2, 1] \/ (
        triples[t1, 1] = triples[t2, 1] /\ (
            triples[t1, 2] <= triples[t2, 2] \/ (
                triples[t1, 2] = triples[t2, 2] /\ triples[t1, 3] < triples[t2, 3]
            )
        )
    )
);

solve satisfy;

% Output the set of triples
output [
    "{",
    "\"sets\": [",
    join(",", [
        "[" ++ join(",", [show(triples[t, i]) | i in 1..3]) ++ "]" | t in 1..num_triples
    ]),
    "]",
    "}"
];
```

