constraint men >= 0;
constraint women >= 0;
constraint children >= 0;

% Since the number of people cannot be negative and must be an integer, we also enforce that the variables are non-negative integers
solve satisfy;

% Output the solution in JSON format
output [
    "{",
    join(",", [
        "\"men\": " ++ show(men),
        "\"women\": " ++ show(women),
        "\"children\": " ++ show(children)
    ]),
