% Constraint: ages are in non-increasing order (A1 >= A2 >= A3)
constraint A1 >= A2 /\ A2 >= A3;

% The problem statement implies that there are at least two possible combinations 
% of ages that have the same sum (otherwise, the mathematician would have been 
% able to determine the ages after knowing the sum). We will use this information 
% to find the correct ages.

% First, let's generate all possible combinations of ages that multiply to 36
% and count how many times each sum occurs.
set of int: PossibleSums = {A1 + A2 + A3 | A1 in Factors, A2 in Factors, A3 in Factors where A1 * A2 * A3 == 36};

% Count occurrences of each sum
array[PossibleSums] of var 0..10: count;

