% Nontransitive Dice Problem

% Number of dice and faces per die
int: num_dice = 5;
int: num_faces = 6;

% Define the beats relationships between the choices (Rock, Paper, Scissors, Lizard, Spock)
set of int: choices = 1..num_dice;
array[choices, choices] of bool: beats = 
    array2d(choices, choices, 
            [false, false, true, true, false,
             true, false, false, true, false,
             false, true, false, false, true,
             false, false, true, false, true,
             true, false, false, false, false]);

% Decision Variables: the faces of the dice
array[1..num_dice] of var set of int: dice;

% Constraints: each die has num_faces faces
constraint forall (i in 1..num_dice) (card(dice[i]) = num_faces);

% Constraints: the values on the faces are between 1 and num_dice*num_faces
constraint forall (i in 1..num_dice, j in 1..num_faces) (min(dice[i]) >= 1 /\ max(dice[i]) <= num_dice*num_faces);

% Constraints: the dice are non-transitive, i.e., the beats relationships are satisfied
constraint forall (i, j in choices where beats[i, j]) 
    (sum(k in dice[i]) (k > min(dice[j])) > num_faces div 2);

% Constraints: the dice have distinct faces
constraint forall (i, j in 1..num_dice where i < j) (disjoint(dice[i], dice[j]));

% Redundant constraint to improve propagation: ordering of the minimum face value of each die
constraint forall (i in 2..num_dice) (min(dice[i-1]) < min(dice[i]));

solve satisfy;

% Output the dice as a list of lists
output ["{\"dice\": [", 
        join(",", [ "[" ++ join(",", [show(k) | k in sorted(set2array(dice[i]))]) ++ "]" | i in 1..num_dice]),
        "]}"];
```

