var Nationalities: x;
var Nationalities: y;
var Nationalities: z;

% american, english, french represent the players with the respective nationalities
var Players: american;
var Players: y_american; % Y passed three hearts to the American
var Players: english;
var Players: french;

% Constraints
constraint all_different([x, y, z]); % Each player has a different nationality
constraint all_different([american, english, french]); % Each nationality is assigned to a different player

% Y passed three hearts to the American
constraint y_american = (american + 1) mod 3;

% The person who passed cards to the Frenchwoman is not Y (since Y passed to the American)
% and is not the Frenchwoman herself, so it must be either X or Z.
% X passed the queen of spades and two diamonds to the person who passed their cards to the French.
constraint (x = (french + 1) mod 3) \/ (z = (french + 1) mod 3);

% X, Y, Z are distinct players, so their nationalities are distinct and are related to the variables american, english, french
constraint x = american \/ x = english \/ x = french;
constraint y = american \/ y = english \/ y = french;
constraint z = american \/ z = english \/ z = french;

% Y is not the American (since Y passed to the American)
constraint y != american;

% X passed to the person who passed to the French, so that person cannot be Y (as Y passed to American)
% and cannot be French (as they passed to French). So, it must be the remaining nationality.
constraint (x = (french + 1) mod 3) -> (y_american != french);

% Relate the nationality variables to the player variables
constraint (x = y_american) \/ (y = y_american) \/ (z = y_american);

solve satisfy;

output ["{",
