% Define the decision variables
% x[i, j] = 1 if a coin is placed at cell (i, j), 0 otherwise
array[1..n, 1..n] of var 0..1: x;

% z is the sum of the quadratic horizontal distance from the main diagonal
var int: z;

% Constraints
constraint forall (i in 1..n) (
    sum(j in 1..n)(x[i, j]) = coins_per_row_column
);

constraint forall (j in 1..n) (
    sum(i in 1..n)(x[i, j]) = coins_per_row_column
);

constraint z = sum(i in 1..n, j in 1..n)(x[i, j] * (i - j) * (i - j));

% Solve to minimize z
solve minimize z;

% Output the solution in JSON format
output [
    "{",
    "\"x\": " ++ show([ [ x[i, j] | j in 1..n] | i in 1..n]) ++ ",",
