    "\"open_warehouse\": [" ++ join(", ", [show(open_warehouse[w]) | w in 1..num_warehouses]) ++ "],",
    "\"ships\": [",
    join(",\n", [ "\"" ++ show(w) ++ "\": [" ++ join(", ", [show(ships[w, r]) | r in 1..num_regions]) ++ "]" | w in 1..num_warehouses]),
    "]",
    "}"
];
