include "globals.mzn";

% Input data
int: num_coins = length(init);
int: num_moves;
array[1..num_coins] of int: init;

% Decision Variables
array[1..num_moves, 1..num_coins] of var 0..1: coins;
array[1..num_moves] of var 1..num_coins: steps;

% Initial configuration
constraint coins[1, ..] = init;

% Transition constraints: a move flips a coin
constraint forall(m in 1..num_moves-1) (
    coins[m+1, ..] = coins[m, ..] /\
    (let {int: coin = steps[m]} in 
        coins[m+1, coin] = 1 - coins[m, coin]
    )
);

% Final state is either all heads or all tails
constraint forall(i in 1..num_coins-1) (
    coins[num_moves, i] = coins[num_moves, i+1]
);

